with races as (select p.id,p.race_date,p.track,p.race_no,p.frozen_at,p.post_time,p.payload,o.result,o.settled_at,coalesce(r.field_payload->'race'->>'surface',o.result->'metadata'->>'surface') as surface,coalesce((r.field_payload->'race'->>'distance')::int,(o.result->'metadata'->>'distance')::int) as distance from public.official_predictions p join public.official_results o using(race_date,track,race_no,circuit) left join public.official_races r using(race_date,track,race_no,circuit) where p.circuit='JRA' and p.status='FROZEN' and p.race_date between '2026-10-17' and '2026-11-15'), per_race as (select race_date,track,race_no,surface,distance,jsonb_array_length(payload->'runners') as horses,frozen_at<post_time as frozen_before_post,settled_at>=post_time as result_after_post,(select count(distinct f->>'horse_no') from jsonb_array_elements(result->'finishers') f where (f->>'finish')::int between 1 and 3 and (exists(select 1 from jsonb_array_elements(payload->'top5') t where t->>'horse_no'=f->>'horse_no') or payload->'eye'->>'horse_no'=f->>'horse_no')) as captured,(select count(*) from jsonb_array_elements(result->'finishers') f where (f->>'finish')::int=1 and f->>'horse_no'=(select t->>'horse_no' from jsonb_array_elements(payload->'runners') t where t->>'rank'='1' limit 1)) as leader_win,(select count(*) from jsonb_array_elements(result->'finishers') f where (f->>'finish')::int between 1 and 3 and f->>'horse_no'=(select t->>'horse_no' from jsonb_array_elements(payload->'runners') t where t->>'rank'='1' limit 1)) as leader_top3 from races) select 'ALL_TURF' as cohort,count(*) as races,sum(horses) as horses,sum(captured) as saved_prediction_captures,sum(leader_win) as leader_wins,sum(leader_top3) as leader_top3,count(*) filter(where not frozen_before_post) as invalid_freeze_times,count(*) filter(where not result_after_post) as unsettled_timing from per_race where surface='芝' union all select 'TURF_LE1800',count(*),sum(horses),sum(captured),sum(leader_win),sum(leader_top3),count(*) filter(where not frozen_before_post),count(*) filter(where not result_after_post) from per_race where surface='芝' and distance<=1800;
